namespace App;
public static class Program {
    private static int Double(int value) => value * 2;
    public static void Main(int unused) { Print("wrong entry"); }
    public static void Main() {
        Print(Double(3)); Print(Pricing.Prices.Total(count: 4));
        Print(Pricing.Prices.Total(2, fee: 7));
    }
}

